-- FLL-TP-RHIZOM-2023 · engineer hints on every field, equation and compliance requirement (hint wave 2026-10-05).
-- Each description now carries a German hint and an English part after the marker "[EN] " (src/lib/eval/hint-text.ts; the form
-- renders the part of the page locale; the approval refusal prints the whole text as "Hinweis" for a block gate without its inputs).
-- Content authored from the printed guideline pages (rendered PDF read in the authoring session; the authoring JSON in the vault
-- carries a source string with the printed page per hint); every number / limit / clause in a hint is traceable to those pages.
-- SAFETY: text only (fields.description, equations.description, compliance_requirements.description); no field, equation, gate,
-- value or severity changes. The pre-block descriptions (encoder notes) are restored by the rollback and kept in the inventory JSON.
-- STAGED — not applied. Apply: node scripts/apply-migration.mjs scripts/migrations/20261005173100_fll_tp_rhizom_followup_hints.sql
-- Rollback: scripts/migrations/rollback-20261005173100_fll_tp_rhizom_followup_hints.sql
BEGIN;
UPDATE fields x SET description = 'Werkstoff der Abdichtung, der den Nachweisweg in RHZ-03 bestimmt. Nach § 1 gelten Abdichtungen, die aufgrund ihrer werkstoffspezifischen Eigenschaften als wurzel- und rhizomfest gelten (z. B. Stahl, Beton, PEHD), ohne gesonderten Nachweis nach FLL-Prüfverfahren; „gup" steht für GUP-Abdichtungen, auf die die Gewässerabdichtungsrichtlinien dieselbe Eigenschaft beziehen. Jeder andere Werkstoff (z. B. PVC-P, EPDM, Bitumen, PELD) ist „sonstige" und geht den Prüfweg.
[EN] Material of the sealing; it decides the proof route in RHZ-03. Under § 1, sealings that count as root- and rhizome-resistant by their material properties (e.g. steel, concrete, PEHD) need no separate proof by an FLL test procedure; "gup" stands for GUP sealings, to which the water-body sealing guidelines attribute the same property. Any other material (e.g. PVC-P, EPDM, bitumen, PELD) is "sonstige" and takes the test route.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-02' AND x.symbol = 'werkstoff_klasse';
UPDATE fields x SET description = 'Hauptschalter des Verfahrens: „pruefung" = Nachweis durch die Prüfung nach diesem Verfahren (alle Prüfblätter RHZ-04 bis RHZ-20 werden eingeblendet); „werkstoffspezifisch" = der Werkstoff gilt nach § 1 ohne gesonderten Nachweis als wurzel- und rhizomfest (Stahl, Beton, PEHD, GUP) — die Prüfblätter bleiben ausgeblendet und RHZ-21 bescheinigt „werkstoffspezifisch rhizomfest". Ohne Antwort bleibt RHZ-21 gesperrt.
[EN] Main switch of the procedure: "pruefung" = proof by the test described in this procedure (all test sheets RHZ-04 to RHZ-20 are shown); "werkstoffspezifisch" = the material counts as root- and rhizome-resistant without a separate proof under § 1 (steel, concrete, PEHD, GUP) — the test sheets stay hidden and RHZ-21 certifies "material-specifically rhizome-resistant". Without an answer RHZ-21 stays blocked.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-03' AND x.symbol = 'nachweis_route';
UPDATE fields x SET description = 'Nur auf dem werkstoffspezifischen Weg: kurze Begründung, warum der Werkstoff ohne Prüfung als wurzel- und rhizomfest gilt — Werkstoff und Quelle nennen (§ 1: „z. B. Stahl, Beton, PEHD"). Der Text erscheint in der Bescheinigung RHZ-21.
[EN] Material-based route only: a short reason why the material counts as root- and rhizome-resistant without a test — name the material and the source (§ 1: "e.g. steel, concrete, PEHD"). The text appears in the certificate RHZ-21.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-03' AND x.symbol = 'nachweis_begruendung';
UPDATE fields x SET description = 'Nur auf dem werkstoffspezifischen Weg: Ja, wenn die Abdichtung einer intensiveren Beanspruchung durch die Bepflanzung ausgesetzt ist (§ 1 nennt Vegetation für Pflanzenkläranlagen und Aufbereitungsbereiche von Schwimmteichen). Dann verlangt § 1 die Prüfung nach diesem Verfahren — das Warn-Tor REQ-RHZ03-INTENSIV meldet den Widerspruch zum gewählten Weg.
[EN] Material-based route only: Yes if the sealing is exposed to more intensive loading from the planting (§ 1 names vegetation for constructed wetlands and the treatment zones of swimming ponds). Then § 1 requires the test described in this procedure — the warning gate REQ-RHZ03-INTENSIV flags the conflict with the chosen route.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-03' AND x.symbol = 'intensive_bepflanzung';
UPDATE compliance_requirements x SET description = 'Warnung, kein Sperrtor: gilt nur auf dem werkstoffspezifischen Weg und meldet, wenn „intensivere Beanspruchung durch die Bepflanzung" mit Ja beantwortet ist. § 1: bei intensiverer Beanspruchung (z. B. Pflanzenkläranlagen, Aufbereitungsbereiche von Schwimmteichen) ist die Prüfung nach diesem Verfahren erforderlich — dann den Weg „pruefung" wählen oder die Entscheidung begründen.
[EN] Warning, not a blocker: applies only on the material-based route and flags when "more intensive loading from the planting" is answered Yes. § 1: under more intensive loading (e.g. constructed wetlands, treatment zones of swimming ponds) the test described in this procedure is required — choose the route "pruefung" or justify the decision.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-03' AND x.code = 'REQ-RHZ03-INTENSIV';
UPDATE compliance_requirements x SET description = 'Warnung, kein Sperrtor: auf dem werkstoffspezifischen Weg soll der Werkstoff einer der genannten Klassen sein (Stahl, Beton, PEHD nach § 1; GUP nach den Gewässerabdichtungsrichtlinien). „sonstige" löst die Warnung aus, weil § 1 die Liste nur beispielhaft („z. B.") führt — die Begründung in RHZ-03 muss dann den Werkstoff und die Quelle nennen.
[EN] Warning, not a blocker: on the material-based route the material should be one of the named classes (steel, concrete, PEHD under § 1; GUP under the water-body sealing guidelines). "sonstige" raises the warning because § 1 gives the list only as examples ("z. B.") — the reason in RHZ-03 must then name the material and the source.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-03' AND x.code = 'REQ-RHZ03-WERKSTOFF';
COMMIT;
